'use strict';
const E=RoomEngine,D=ROOM_DATA,$=s=>document.querySelector(s),fmt=r=>r.id.slice(0,2)+' '+r.id.slice(2),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let live=true,followToday=true,lastDate=E.berlin().date;
$('#date').value=lastDate;$('#time').value=E.hhmm(E.berlin().minute);
const duration=m=>m>=60?`${Math.floor(m/60)} Std.${m%60?' '+m%60+' Min.':''}`:`${m} Min.`;
function label(s){if(s.type==='free')return `${s.tentative?'Vsl. planfrei':'Planfrei'} bis ${E.hhmm(s.end)}`;if(s.type==='busy')return `Belegt bis ${E.hhmm(s.end)}`;if(s.type==='uncertain')return 'Uhrzeit unklar';return 'Keine Plandaten'}
function sublabel(s){if(s.type==='free')return `Noch ${duration(s.remaining)}`;if(s.type==='busy')return s.nextFree!==undefined?`Planfrei ab ${E.hhmm(s.nextFree)}`:'Danach keine gesicherten Daten';if(s.type==='uncertain')return 'Abendtermin nicht sicher lesbar';return 'Keine freie Zeit ableitbar'}
function dateText(date){return new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'))}
function render(){const now=E.berlin(),date=$('#date').value,t=E.min($('#time').value);if(!date||!Number.isFinite(t))return;$('#clock').textContent=E.hhmm(now.minute);$('#now').classList.toggle('active',live&&date===now.date);$('#status-heading').textContent=live&&date===now.date?'Jetzt laut Plan frei':`Laut Plan um ${E.hhmm(t)} Uhr`;$('#day-label').textContent=dateText(date);const states=D.rooms.map(r=>({r,s:E.status(r,date,t)}));const frees=states.filter(x=>x.s.type==='free');$('#count').textContent=`${frees.length} von ${D.rooms.length} planfrei${frees.some(x=>x.s.tentative)?' · teils vorläufig':''}`;
$('#cards').innerHTML=[...states].sort((a,b)=>(a.s.type!=='free')-(b.s.type!=='free')||(a.s.type==='free'&&b.s.type==='free'?b.s.remaining-a.s.remaining:0)||a.r.id.localeCompare(b.r.id)).map(({r,s})=>`<button class="room-card ${s.type}" data-room="${r.id}" aria-label="${fmt(r)}: ${label(s)}. Details öffnen"><strong>${fmt(r)}${r.tentative?' <sup style="font-size:12px">*</sup>':''}</strong><span class="name">${r.name}</span><span class="state">${label(s)}</span><span class="duration">${sublabel(s)}</span></button>`).join('');
const pos=n=>(n-480)*1.4;
let html='<div class="col-title time-title">Uhr</div>'+D.rooms.map(r=>`<button class="col-title" data-room="${r.id}"><strong>${fmt(r)}${r.tentative?' *':''}</strong><small>${r.name}</small></button>`).join('');
html+='<div class="time-axis">'+Array.from({length:13},(_,i)=>`<span style="top:${i*84}px">${E.hhmm(480+i*60)}</span>`).join('')+'</div>';
html+=D.rooms.map(r=>{let inside=E.segments(r,date).filter(s=>s.type==='unknown').map(s=>`<div class="no-data" style="top:${pos(s.start)}px;height:${(s.end-s.start)*1.4}px">Keine Plandaten</div>`).join('');if(E.weekday(date)<=5)inside+=E.events(r,date).map(e=>{const a=E.min(e.start),b=E.min(e.end),title=e.uncertain?'Zeit unklar':`${e.start}–${e.end}`;return `<button class="event ${e.title==='Systemzeit'?'system':''} ${e.uncertain?'uncertain':''} ${b-a<=30?'compact':''}" data-room="${r.id}" style="top:${pos(a)}px;height:${(b-a)*1.4-2}px" title="${esc(e.title)} · ${title}${r.tentative?' · Tageszuordnung vorläufig':''}"><time>${title}</time><span class="event-title">${esc(e.title)}</span></button>`}).join('');if(t>=480&&t<1200)inside+=`<div class="now-line ${live&&date===now.date?'':'selected-line'}" style="top:${pos(t)}px"></div>`;return `<div class="room-column" aria-label="${fmt(r)}">${inside}</div>`}).join('');$('#calendar').innerHTML=html;$('#event-count').textContent=D.rooms.reduce((n,r)=>n+r.events.length,0)}
function openRoom(id){const r=D.rooms.find(r=>r.id===id),date=$('#date').value,events=E.events(r,date);$('#detail-title').textContent=fmt(r)+' · '+r.name;let note=r.tentative?'Tageszuordnung vorläufig: Im Screenshot fehlen Tagesüberschriften und Kalenderwoche. Die Spalten wurden als Montag–Sonntag interpretiert. ':'';if(r.id==='SI0024')note+='Dienstagabend: Die genaue Zeit des letzten Blocks ist unleserlich. 18:00–19:30 Uhr ist ein vorsorglicher Unsicherheitsbereich. Nutzung laut Aushang grundsätzlich nur für Teilnehmende der Veranstaltungen. ';$('#detail-content').innerHTML=(note?`<p class="detail-note">${note}</p>`:'')+`<p>${dateText(date)}</p>`+(events.length?'<ul class="detail-events">'+events.map(e=>`<li><time>${e.uncertain?'Zeit unklar (vorsorglich 18:00–19:30)':`${e.start}–${e.end}`} Uhr</time>${esc(e.title)}</li>`).join('')+'</ul>':`<p>${E.weekday(date)>5?'Für diesen Tag gibt es keine Plandaten.':'Im sichtbaren Wochenplan sind für diesen Tag keine Termine eingetragen.'}</p>`)+`<p class="detail-source-label">Quelle: ${esc(r.sourceFile)}</p><p class="detail-source-label">Wöchentliches Planmuster; Gültigkeitszeitraum nicht angegeben. Keine Live-Belegung.</p>`;$('#details').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-room]');if(b)openRoom(b.dataset.room)});$('#close').onclick=()=>$('#details').close();$('#details').addEventListener('click',e=>{if(e.target===$('#details')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#date').onchange=()=>{if(!$('#date').value)return;followToday=$('#date').value===E.berlin().date;render()};$('#time').onchange=()=>{if(!$('#time').value)return;live=false;render()};$('#today').onclick=$('#now').onclick=()=>{const n=E.berlin();live=followToday=true;$('#date').value=n.date;$('#time').value=E.hhmm(n.minute);render()};function move(n){const d=new Date($('#date').value+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);$('#date').value=d.toISOString().slice(0,10);followToday=false;render()}$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);
function tick(){const n=E.berlin();if(followToday&&n.date!==lastDate)$('#date').value=n.date;lastDate=n.date;if(live)$('#time').value=E.hhmm(n.minute);render()}setInterval(tick,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});render();
